using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ARC.Archivos;using GraphApi.Services.ARC.Archivos;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ARC.Archivos{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Archivos: creación, actualización y eliminación.")]    public class ArchivosMutation    {        [Authorize]        [GraphQLName("createArchivos")]        [GraphQLDescription("Crea un nuevo Archivo usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadArchivos> CreateArchivosAsync(            [GraphQLDescription("Datos necesarios para crear el Archivo.")]            clCreateArchivos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Archivo.")]            IArchivosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateArchivos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateArchivos")]        [GraphQLDescription("Actualiza los campos especificados de un Archivo existente.")]        public async Task<clReadArchivos?> UpdateArchivosAsync(            [GraphQLDescription("Datos del Archivo a actualizar.")]            clUpdateArchivos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Archivo.")]            IArchivosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateArchivos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteArchivos")]        [GraphQLDescription("Elimina un Archivo por su ID.")]        public async Task<bool> delArchivosAsync(            [GraphQLDescription("ID del Archivo a eliminar.")]            int nArchivosID,            [Service]            [GraphQLDescription("Servicio para operaciones de Archivo.")]            IArchivosService objService        )        {            return await objService.DeleteArchivos(nArchivosID);        }    }}